import zlib, subprocess
EXE="/workspace/executable"
def block_raw(data, block_size=128*1024, level=6, strategy=0, independent=False, use_dict=True):
    if len(data)==0:
        comp=zlib.compressobj(level, zlib.DEFLATED, -15, 8, strategy)
        return comp.compress(b"")+comp.flush()
    blocks=[data[i:i+block_size] for i in range(0,len(data),block_size)]
    out=b""
    for idx, blk in enumerate(blocks):
        if idx==0 or independent or not use_dict:
            comp=zlib.compressobj(level, zlib.DEFLATED, -15, 8, strategy)
        else:
            zdict=blocks[idx-1][-32768:]
            comp=zlib.compressobj(level, zlib.DEFLATED, -15, 8, strategy, zdict)
        raw=comp.compress(blk)
        raw+=comp.flush(zlib.Z_SYNC_FLUSH if idx<len(blocks)-1 else zlib.Z_FINISH)
        out+=raw
    return out

data=open("/workspace/pigz.1","rb").read()*200
for lvl in [1,2,3,4,5,6,7,8,9]:
    r=subprocess.run([EXE,f"-{lvl}"], input=data, capture_output=True)
    pigz_raw=r.stdout[10:-8]
    my=block_raw(data, level=lvl)
    print(f"lvl {lvl} pigz {len(pigz_raw)} my {len(my)} equal={pigz_raw==my}")
    if pigz_raw!=my:
        # find diff
        for i in range(min(len(pigz_raw),len(my))):
            if pigz_raw[i]!=my[i]:
                print(f"  diff at {i}")
                break
