def parse_args(prog, args, opts, env_name=None):
    """
    Parse args list (tokens) in order.
    Returns (files, exit_code, exit_msg) where exit_code is not None if should exit early (help/version/license or abort).
    For abort, exit_code is 22 and exit_msg is message to print (or None if quiet).
    For help/version/license, exit_code 0 and handling done by caller.
    files is list of file args collected (only for command line, not for env? For env, files cause abort).
    """
    # args is list of strings (already split)
    # opts is Options object to update
    # env_name is None for command line, or "GZIP"/"PIGZ" for env (to produce correct abort message for files)
    files = []
    i = 0
    end_of_options = False
    while i < len(args):
        arg = args[i]
        if env_name is not None:
            # env args: files not allowed. But how to detect files? Any arg that is not an option?
            # For env, we need to parse same as command line but if we encounter a file (including "-" or "--" or non-option), abort.
            # However, for env, "--" would be considered file? Probably yes, since files not allowed.
            # We'll handle below: if arg is file-like, abort.
            pass
        if end_of_options:
            # all remaining are files (even if start with -)
            # But what about "-" after "--"? Earlier test: "-- -" gave "skipping: - does not exist" (so "-" after -- is treated as file named "-", not stdin). Good.
            files.append(arg)
            i+=1
            continue
        if arg == "--":
            if env_name is not None:
                # In env, "--" is considered file? Let's test: GZIP="--" ? Probably error "cannot provide files..."? Let's assume yes.
                return (None, 22, f"{prog}: abort: cannot provide files in {env_name} environment variable\n")
            end_of_options = True
            i+=1
            continue
        if arg == "-":
            # stdin marker (but not after --, which is handled above)
            if env_name is not None:
                return (None, 22, f"{prog}: abort: cannot provide files in {env_name} environment variable\n")
            files.append(arg)
            i+=1
            continue
        if arg.startswith("--"):
            # long option
            name = arg[2:]
            # check for "=" ? Original treats "--blocksize=128" as invalid option (full string). So any "=" in name means invalid.
            if "=" in name:
                # entire arg is invalid?
                msg = f"{prog}: abort: invalid option: {arg}\n"
                # respect quiet? For abort, if quiet already set, suppress? Earlier -q -Z gave no message. So if opts.quiet, suppress.
                if opts.quiet:
                    return (None, 22, None)
                return (None, 22, msg)
            if name not in LONG_OPTS:
                # check special cases: --ascii, --compress ?
                if name == "ascii":
                    msg = f"{prog}: abort: invalid option: no ascii conversion: -a\n"
                    if opts.quiet:
                        return (None, 22, None)
                    return (None, 22, msg)
                elif name == "compress":
                    msg = f"{prog}: abort: invalid option: --compress\n"
                    if opts.quiet:
                        return (None, 22, None)
                    return (None, 22, msg)
                else:
                    msg = f"{prog}: abort: invalid option: {arg}\n"
                    if opts.quiet:
                        return (None, 22, None)
                    return (None, 22, msg)
            short = LONG_OPTS[name]
            # handle based on short
            if short == "fast":
                opts.level = 1
            elif short == "best":
                opts.level = 9
            elif short in ("A","b","C","p","S","I","J"):
                # need param from next arg
                if i+1 >= len(args):
                    msg = f"{prog}: abort: missing parameter after -{short}\n"
                    if opts.quiet:
                        return (None, 22, None)
                    return (None, 22, msg)
                nxt = args[i+1]
                if nxt.startswith("-"):
                    # missing (even if "-" ? Earlier -S - gave missing, yes)
                    msg = f"{prog}: abort: missing parameter after -{short}\n"
                    if opts.quiet:
                        return (None, 22, None)
                    return (None, 22, msg)
                if nxt == "":
                    # empty param handling: for b/p/I/J => internal error, for S => suffix cannot be empty, for C/A => ok?
                    if short in ("b","p","I","J"):
                        msg = f"{prog}: abort: internal error: empty parameter\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    elif short == "S":
                        msg = f"{prog}: abort: suffix cannot be empty\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    elif short == "C":
                        opts.comment = ""
                        i+=2
                        continue
                    elif short == "A":
                        opts.alias = ""
                        i+=2
                        continue
                # validate numeric for b/p/I/J
                if short == "b":
                    if not is_numeric_param(nxt):
                        msg = f"{prog}: abort: invalid numeric parameter: {nxt}\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    val = int(nxt)
                    if val < 32:
                        msg = f"{prog}: abort: block size too small (must be >= 32K)\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    opts.blocksize = val
                elif short == "p":
                    if not is_numeric_param(nxt):
                        msg = f"{prog}: abort: invalid numeric parameter: {nxt}\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    val = int(nxt)
                    if val == 0:
                        msg = f"{prog}: abort: invalid number of processes: {nxt}\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    opts.processes = val
                elif short in ("I","J"):
                    if not is_numeric_param(nxt):
                        msg = f"{prog}: abort: invalid numeric parameter: {nxt}\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    val = int(nxt)
                    if short == "I":
                        opts.iterations = val
                    else:
                        opts.maxsplits = val
                elif short == "S":
                    if nxt == "":
                        msg = f"{prog}: abort: suffix cannot be empty\n"
                        if opts.quiet:
                            return (None, 22, None)
                        return (None, 22, msg)
                    opts.suffix = nxt
                    opts.suffix_explicit = True
                    opts.format_order.append(('S', nxt))
                elif short == "C":
                    opts.comment = nxt
                elif short == "A":
                    opts.alias = nxt
