                    code, out_stdout, out_stderr, should_exit = res
                    if should_exit:
                        return (None, code, (out_stdout, out_stderr))
                i+=1
                continue
        elif arg.startswith("-") and len(arg) > 1:
            # short bundled options
            # Need to parse char by char, with special handling for digits and params
            j = 1
            consumed_next = False
            abort_happened = False
            abort_msg = None
            abort_code = None
            early_exit = None  # for help/version/license
            while j < len(arg):
                ch = arg[j]
