def get_suffix_and_format(opts):
    # Determine suffix and format based on last among -z/-K/-S, default .gz/gzip
    # opts.format_order is list of ('K',)/( 'z',)/( 'S', suffix)
    # Also opts.zip/zlib flags? But format_order tracks order. If empty, default gzip .gz
    # If last is K => zip .zip, if z => zlib .zz, if S => custom suffix with gzip format
    # Except: what about -S .foo then -z? Last is z => .zz zlib. Good.
    # What about -K then -S? Last S => custom gzip. Good.
    # What about no explicit -S but -z/-K? Use their suffix.
    # What about explicit -S .gz? Then suffix .gz with gzip (same as default).
    if not opts.format_order:
        return (".gz", "gzip")
    last = opts.format_order[-1]
    if last[0] == 'K':
        return (".zip", "zip")
    elif last[0] == 'z':
        return (".zz", "zlib")
    elif last[0] == 'S':
        return (last[1], "gzip")
    return (".gz", "gzip")

